import { v7 } from "uuid";

/**
 * Returns a new UUIDv7 for a GymOs-owned row (handoff rule 13).
 *
 * IDs are generated by the application, never by the database, so a
 * client can create rows offline and commands stay idempotent. UUIDv7
 * leads with a millisecond timestamp, so IDs sort by creation time and
 * index well. Within one process they are strictly increasing, even
 * inside the same millisecond.
 */
export function newId(): string {
  return v7();
}
